select '1. tables exist' as check, case when ( select count(*) from information_schema.tables where table_schema = 'public' and table_name in ('planner_blocks', 'planner_presets') ) = 2 then 'OK' else 'PROBLEM - 0036 did not run' end as result; select '2. RLS on' as check, case when count(*) = 2 then 'OK' else 'PROBLEM - only ' || count(*) || ' of 2 tables have it' end as result from pg_tables where schemaname = 'public' and tablename in ('planner_blocks', 'planner_presets') and rowsecurity; select '3. owner-only, one policy each' as check, case when count(*) = 2 then 'OK' else 'PROBLEM - expected 2 policies, found ' || count(*) end as result from pg_policies where schemaname = 'public' and tablename in ('planner_blocks', 'planner_presets'); select '4. policies check the owner' as check, case when count(*) = 2 then 'OK' else 'PROBLEM - ' || (2 - count(*)) || ' policy/policies do not test owner_id' end as result from pg_policies where schemaname = 'public' and tablename in ('planner_blocks', 'planner_presets') and coalesce(qual, '') like '%owner_id%' and coalesce(with_check, '') like '%owner_id%'; select '5. block shape enforced' as check, case when ( select count(*) from pg_constraint where conrelid = to_regclass('public.planner_blocks') and conname in ('planner_blocks_ends_after_start', 'planner_blocks_date_matches_repeat') ) = 2 then 'OK' else 'PROBLEM - a shape constraint is missing, or 0036 did not run' end as result; select '6. weekday kept honest' as check, case when exists ( select 1 from pg_trigger where tgrelid = to_regclass('public.planner_blocks') and tgname = 'planner_blocks_weekday' ) then 'OK' else 'PROBLEM - the trigger is missing, or 0036 did not run' end as result; select '7. calendar link unlinks, not deletes' as check, case when exists ( select 1 from pg_constraint where conrelid = to_regclass('public.planner_blocks') and contype = 'f' and confrelid = to_regclass('public.schedule_events') and confdeltype = 'n' ) then 'OK' else 'PROBLEM - wrong or missing foreign key, or 0036 did not run' end as result; select 'data: no block on the wrong day' as check, case when count(*) = 0 then 'OK' else 'PROBLEM - ' || count(*) || ' block(s) sit on the wrong weekday' end as result from public.planner_blocks b where b.on_date is not null and b.weekday <> extract(isodow from b.on_date)::int - 1; select case b.weekday when 0 then 'Mon' when 1 then 'Tue' when 2 then 'Wed' when 3 then 'Thu' when 4 then 'Fri' when 5 then 'Sat' else 'Sun' end as day, to_char((b.start_minute || ' minutes')::interval, 'HH24:MI') as starts, to_char((b.end_minute || ' minutes')::interval, 'HH24:MI') as ends, b.title, case when b.repeats then 'every week' else to_char(b.on_date, 'DD Mon') end as when_, case when b.schedule_event_id is null then '-' else 'on the calendar' end as shared from public.planner_blocks b order by b.repeats desc, b.weekday, b.start_minute;
